    hanzi:
      "现在在中国，越来越多人用手机给钱，所以有些人担心银行可能会关门，因为用手机比去银行方便得多。比如现在，你不但可以在手机银行上给他们寄钱，你还可以在手机上用WeChat或者Alipay给他们转钱，这样不是又快又安全吗？但是，有另一些人，他们认为去银行寄钱取钱比用手机给钱安全一些，所以他们还是会去银行。",
    pinyin:
      "Xiànzài zài zhōngguó, yuè lái yuè duō rén yòng shǒujī gěi qián, suǒyǐ yǒuxiē rén dānxīn yínháng kěnéng huì guānmén, yīnwèi yòng shǒujī bǐ qù yínháng fāngbiàn dé duō. Bǐrú xiànzài, nǐ bùdàn kěyǐ zài shǒujī yínháng shàng gěi tāmen jì qián, nǐ hái kěyǐ zài shǒujī shàng yòng WeChat huòzhě Alipay gěi tāmen zhuǎn qián, zhèyàng bùshì yòu kuài yòu ānquán ma? Dànshì, yǒu lìng yìxiē rén, tāmen rènwéi qù yínháng jì qián qǔ qián bǐ yòng shǒujī gěi qián ānquán yìxiē, suǒyǐ tāmen háishì huì qù yínháng.",
